    has_atm = bool(atmosphere_fx and not any(k in str(atmosphere_fx).lower() for k in ("none", "off", "clean"))) or bool(particle_overlay and not any(k in str(particle_overlay).lower() for k in ("none", "off", "clean")))
    eff_atm = atmosphere_fx if (atmosphere_fx and not any(k in str(atmosphere_fx).lower() for k in ("none", "off", "clean"))) else particle_overlay

    if has_vis or has_sub or has_logo or has_caps or has_atm:
        layered_out = os.path.join(workdir, "final_layered_output.mp4")
